// ===== CONFIGURACIÓN (edita aquí) =====
const DOMINIO_PROPIO = /@equitermindustries\.com\.mx$/i;   // destinatarios internos: se ignoran
const MI_BUZON = 'administracion@equitermindustries.com.mx';
// ======================================

const j = $json;
const asText = (v) => {
  if (!v) return '';
  if (typeof v === 'string') return v;
  if (v.text) return v.text;
  if (Array.isArray(v.value)) return v.value.map((a) => a.address).join(',');
  if (Array.isArray(v)) return v.map((a) => a.address || a).join(',');
  return '';
};
const emails = (s) => (String(s).match(/[A-Z0-9._%+\-]+@[A-Z0-9.\-]+\.[A-Z]{2,}/gi) || []).map((e) => e.toLowerCase());

// Solo destinatarios externos (clientes). Si todos son del dominio propio, no se manda nada.
const externos = [...new Set([...emails(asText(j.to)), ...emails(asText(j.cc))])].filter((e) => !DOMINIO_PROPIO.test(e));

const subject = (j.subject || '').trim();
const body = (j.textPlain || j.text || (j.textHtml || '').replace(/<style[\s\S]*?<\/style>/gi, '').replace(/<[^>]+>/g, ' ')).replace(/\r/g, '').replace(/[ \t]+\n/g, '\n').trim();
const messageId = (j.messageId || j.metadata?.['message-id'] || j.headers?.['message-id'] || (MI_BUZON + '|' + subject + '|' + (j.date || ''))).toString();
const inReplyTo = (j.metadata?.['in-reply-to'] || j.headers?.['in-reply-to'] || '').toString();
const from = emails(asText(j.from))[0] || MI_BUZON;
const attachments = (j.attachments || []).map((a) => a.filename || a.fileName || '').filter(Boolean);

return {
  json: {
    valido: externos.length > 0,
    payload: {
      message_id: messageId,
      from_email: from,
      to: externos.join(', '),
      subject,
      body: body.slice(0, 100000),
      sent_at: j.date ? new Date(j.date).toISOString() : new Date().toISOString(),
      in_reply_to: inReplyTo,
      attachments,
    },
  },
};
